SELECT v.product_id, (SELECT s.name FROM products x JOIN sellers s USING (seller_id) WHERE x.product_id = v.product_id), SUM(oi.line_total_bdt) FROM order_items oi JOIN product_variants v USING (variant_id) WHERE v.product_id IN (SELECT product_id FROM products WHERE name = 'Classic Panjabi') AND oi.order_id IN (SELECT order_id FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2026-01-01 00:00:00' AND o.order_at < TIMESTAMP '2026-11-01 00:00:00') GROUP BY v.product_id
